import React from "react";
import headerBg from '../img/header-bg.png'; // точное имя файла

const Home = () => {
  return (
    <div
      style={{
        width: '100%',
        height: '500px',
        borderRadius: '1px so',
        textAlign: "center",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        minHeight: "100vh",
        gap: "20px",        
        padding: "20px"
      }}
    >
      <h1>Hi, my name is <strong>John Doe</strong></h1>
      <h2>a frontend developer</h2>
      <h3>with passion for learning and creating.</h3>

      <img
        src={headerBg} // используем импортированный файл
        alt="Profile"
        style={{ width: "200px", borderRadius: "50%" }}
      />

      <a href="/CV.pdf" download>
        <button
          style={{
            padding: "10px 20px",
            fontSize: "16px",
            cursor: "pointer",
            borderRadius: "5px",
            backgroundColor: "#4CAF50",
            color: "white",
            border: "none",
          }}
        >
          Download CV
        </button>
      </a>
    </div>
  );
};

export default Home;
